  "Manage download clients for automated downloads. Downloads use priority order with automatic fallback; Real-Debrid files are copied back to QuestarrNG before import.":
    {
      es: "Administra clientes de descarga automática. Las descargas siguen el orden de prioridad y pasan al siguiente cliente si hace falta; los archivos de Real-Debrid se copian a QuestarrNG antes de importarlos.",
      "zh-Hans":
        "管理自动下载客户端。下载按优先级顺序执行，并在需要时自动切换；Real-Debrid 文件会在导入前复制回 QuestarrNG。",
      hi: "स्वचालित डाउनलोड क्लाइंट प्रबंधित करें। डाउनलोड प्राथमिकता क्रम और स्वचालित फ़ॉलबैक का उपयोग करते हैं; Real-Debrid फ़ाइलें आयात से पहले QuestarrNG में वापस कॉपी की जाती हैं।",
      de: "Verwalte Download-Clients für automatische Downloads. Es gilt eine Prioritätsreihenfolge mit automatischem Wechsel; Real-Debrid-Dateien werden vor dem Import zurück nach QuestarrNG kopiert.",
      ja: "自動ダウンロード用のクライアントを管理します。優先順位に沿ってダウンロードし、必要に応じて自動で切り替えます。Real-Debrid のファイルはインポート前に QuestarrNG へコピーされます。",
      fr: "Gérez les clients de téléchargement automatique. Les téléchargements suivent un ordre de priorité avec bascule automatique ; les fichiers Real-Debrid sont recopiés dans QuestarrNG avant l’importation.",
      "pt-BR":
        "Gerencie clientes de download automático. Os downloads seguem uma ordem de prioridade com alternância automática; arquivos do Real-Debrid são copiados de volta para o QuestarrNG antes da importação.",
      ar: "أدر عملاء التنزيل التلقائي. تُستخدم أولوية التنزيل مع التحويل التلقائي عند الحاجة؛ وتُنسخ ملفات Real-Debrid إلى QuestarrNG قبل الاستيراد.",
      ko: "자동 다운로드 클라이언트를 관리합니다. 다운로드는 우선순위에 따라 진행되고 자동 대체가 적용됩니다. Real-Debrid 파일은 가져오기 전에 QuestarrNG로 복사됩니다.",
      "zh-Hant":
        "管理自動下載用戶端。下載會依優先順序執行，並在需要時自動切換；Real-Debrid 檔案會在匯入前複製回 QuestarrNG。",
      vi: "Quản lý ứng dụng tải xuống tự động. Tải xuống theo thứ tự ưu tiên và tự chuyển sang ứng dụng khác khi cần; tệp Real-Debrid được sao chép về QuestarrNG trước khi nhập.",
      id: "Kelola klien unduhan otomatis. Unduhan memakai urutan prioritas dengan pengalihan otomatis; file Real-Debrid disalin kembali ke QuestarrNG sebelum diimpor.",
    },
