  "Choose the platforms you use. Only these appear in platform filters across the app, and only these are eligible for import. Leave everything unchecked to show all platforms.":
    {
      es: "Elige las plataformas que uses. Sólo estos aparecen en filtros de plataforma a través de la aplicación, y sólo estos son elegibles para la importación. Deja todo sin comprobar para mostrar todas las plataformas.",
      "zh-Hans":
        "选择您使用的平台 。 只有这些在跨应用程序的平台过滤器中出现,只有这些软件才有资格被导入. 任由一切不受限制地显示所有平台.",
      hi: "आप जिस प्लेटफॉर्म का उपयोग करते हैं उसे चुनें। केवल ये ऐप में प्लेटफॉर्म फिल्टर में दिखाई देते हैं और केवल ये आयात के लिए पात्र हैं। सभी प्लेटफार्मों को दिखाने के लिए सब कुछ अनचेक छोड़ दें।",
      de: "Wählen Sie die Plattformen, die Sie verwenden. Nur diese erscheinen in Plattformfiltern in der App und nur diese sind zum Import berechtigt. Lassen Sie alles ungeprüft, um alle Plattformen anzuzeigen.",
      ja: "使用するプラットフォームを選択します。 これらは、アプリ全体でプラットフォームフィルタに表示され、これらのみがインポート対象となります。 すべてのプラットフォームを表示するためにチェックされていないすべてを残します。",
      fr: "Choisissez les plateformes que vous utilisez. Seulement ceux-ci apparaissent dans les filtres de plate-forme à travers l'application, et ceux-ci sont admissibles à l'importation. Laissez tout décoché pour montrer toutes les plateformes.",
      "pt-BR":
        "Escolha as plataformas que você usa. Somente elas aparecem nos filtros de plataforma do app e podem ser importadas. Deixe tudo desmarcado para mostrar todas as plataformas.",
      ar: "حدّد المنصات التي تستخدمها. ستظهر هذه المنصات فقط في فلاتر المنصة في التطبيق، وستكون وحدها مؤهلة للاستيراد. اترك جميع الخيارات دون تحديد لعرض كل المنصات.",
      ko: "사용하는 플랫폼을 선택하세요. 선택한 플랫폼만 앱의 플랫폼 필터에 표시되고 가져올 수 있습니다. 아무것도 선택하지 않으면 모든 플랫폼을 표시합니다.",
      "zh-Hant":
        "選擇您使用的平台。應用程式的平台篩選器只會顯示這些平台，而且只有這些平台可供匯入。取消勾選所有項目即可顯示所有平台。",
      vi: "Chọn các nền tảng bạn sử dụng. Chỉ những nền tảng này xuất hiện trong bộ lọc nền tảng của ứng dụng và đủ điều kiện nhập. Bỏ chọn tất cả để hiển thị mọi nền tảng.",
      id: "Pilih platform yang Anda gunakan. Hanya ini muncul dalam filter platform di seluruh aplikasi, dan hanya ini yang memenuhi syarat untuk impor. Tinggalkan semuanya tidak diperiksa untuk menunjukkan semua platform.",
    },
  "Choose whether shelved and completed games send these notifications. Applies to both In-App and Apprise. Games are still checked for available content.":
    {
      es: "Elige si los juegos archivados y completados envían estas notificaciones. Se aplica tanto a las notificaciones de la aplicación como a Apprise. Los juegos se siguen comprobando para detectar contenido disponible.",
      "zh-Hans":
        "选择是否为已归档和已完成的游戏发送这些通知。此设置同时适用于应用内通知和 Apprise。系统仍会检查这些游戏是否有可用内容。",
      hi: "चुनें कि संग्रहित और पूरे हो चुके गेम ये सूचनाएँ भेजें या नहीं। यह ऐप के अंदर और Apprise, दोनों पर लागू होता है। उपलब्ध सामग्री के लिए गेम की जाँच फिर भी होती रहेगी।",
      de: "Legen Sie fest, ob archivierte und abgeschlossene Spiele diese Benachrichtigungen auslösen. Dies gilt sowohl für In-App-Benachrichtigungen als auch für Apprise. Die Spiele werden weiterhin auf verfügbare Inhalte geprüft.",
      ja: "アーカイブ済みまたは完了済みのゲームについて、これらの通知を送るかどうかを選択します。アプリ内通知と Apprise の両方に適用されます。ゲームの配信可能なコンテンツは引き続き確認されます。",
      fr: "Choisissez si les jeux archivés ou terminés déclenchent ces notifications. Ce réglage s’applique aux notifications dans l’application et à Apprise. La disponibilité de contenu pour ces jeux reste vérifiée.",
      "pt-BR":
        "Escolha se jogos arquivados e concluídos devem enviar estas notificações. A opção vale tanto para notificações no app quanto para o Apprise. A disponibilidade de conteúdo desses jogos continuará sendo verificada.",
      ar: "اختر ما إذا كانت الألعاب المؤرشفة والمكتملة ترسل هذه الإشعارات. ينطبق ذلك على الإشعارات داخل التطبيق وApprise. وسيستمر التحقق من توفر محتوى لهذه الألعاب.",
      ko: "보관했거나 완료한 게임에 대해 이 알림을 보낼지 선택하세요. 앱 내 알림과 Apprise 모두에 적용됩니다. 게임에 이용 가능한 콘텐츠가 있는지는 계속 확인합니다.",
      "zh-Hant":
        "選擇是否為已封存及已完成的遊戲傳送這些通知。此設定同時適用於應用程式內通知和 Apprise。系統仍會檢查這些遊戲是否有可用內容。",
      vi: "Chọn có gửi thông báo này cho trò chơi đã lưu trữ hoặc hoàn tất hay không. Áp dụng cho cả thông báo trong ứng dụng và Apprise. Hệ thống vẫn kiểm tra nội dung có sẵn cho các trò chơi này.",
      id: "Pilih apakah game yang diarsipkan dan selesai mengirim notifikasi ini. Pengaturan berlaku untuk notifikasi dalam aplikasi dan Apprise. Game tetap diperiksa untuk mengetahui ketersediaan konten.",
    },
  "Choose which stats to include in the image.": {
    es: "Elige qué estadísticas incluir en la imagen.",
    "zh-Hans": "选择图像中要包含哪些数据 。",
    hi: "कौन सा आँकड़े छवि में शामिल करने के लिए चुनें।",
    de: "Wählen Sie aus, welche Statistiken in das Bild aufgenommen werden sollen.",
    ja: "画像に含まれる統計情報を選択します。",
    fr: "Choisissez les statistiques à inclure dans l'image.",
    "pt-BR": "Escolha quais estatísticas incluir na imagem.",
    ar: "اختر أي الإحصائيات التي ستدرج في الصورة",
    ko: "이미지에 포함된 통계를 선택하십시오.",
    "zh-Hant": "選擇影象中要包含哪些資料 。",
    vi: "Chọn số liệu cần bao gồm trong ảnh.",
    id: "Pilih statistik mana yang mesti disertakan dalam gambar.",
  },
