  "Required for DSM login.": {
    es: "Necesario para la entrada DSM.",
    "zh-Hans": "DSM 登录需要 。",
    hi: "DSM लॉगिन के लिए आवश्यक है।",
    de: "Erforderlich für DSM-Login.",
    ja: "DSMログインが必要です。",
    fr: "Requis pour la connexion DSM.",
    "pt-BR": "Requerido para login DSM.",
    ar: "مطلوب لـ (دي إم سي)",
    ko: "DSM 로그인이 필요합니다.",
    "zh-Hant": "DSM 登入需要 。",
    vi: "Cần thiết để đăng nhập DSM.",
    id: "Perlu untuk login DSM.",
  },
  "Required when Prowlarr is reached over plain HTTP, otherwise the API key is not sent and every indexer answers 401. Only for a trusted local network.":
    {
      es: "Necesario cuando se accede a Prowlarr mediante HTTP sin cifrar; de lo contrario, no se envía la clave de API y todos los indexadores responden con 401. Úsalo solo en una red local de confianza.",
      "zh-Hans":
        "通过未加密的 HTTP 访问 Prowlarr 时必须启用，否则不会发送 API 密钥，所有索引器都会返回 401。仅用于可信任的本地网络。",
      hi: "Prowlarr तक बिना एन्क्रिप्शन वाले HTTP से पहुँचने पर यह आवश्यक है; अन्यथा API कुंजी नहीं भेजी जाएगी और हर इंडेक्सर 401 लौटाएगा। इसका उपयोग केवल विश्वसनीय स्थानीय नेटवर्क पर करें।",
      de: "Erforderlich, wenn Prowlarr über unverschlüsseltes HTTP aufgerufen wird. Andernfalls wird der API-Schlüssel nicht gesendet und jeder Indexer antwortet mit 401. Nur in einem vertrauenswürdigen lokalen Netzwerk verwenden.",
      ja: "Prowlarr に暗号化されていない HTTP で接続する場合に必要です。設定しないと API キーが送信されず、すべてのインデクサーが 401 を返します。信頼できるローカルネットワークでのみ使用してください。",
      fr: "Nécessaire lorsque Prowlarr est accessible en HTTP non chiffré ; sinon, la clé API n’est pas envoyée et chaque indexeur répond 401. À utiliser uniquement sur un réseau local de confiance.",
      "pt-BR":
        "Necessário ao acessar o Prowlarr por HTTP sem criptografia; caso contrário, a chave da API não será enviada e todos os indexadores responderão com 401. Use somente em uma rede local confiável.",
      ar: "يلزم ذلك عند الوصول إلى Prowlarr عبر HTTP غير مشفّر؛ وإلا فلن يُرسل مفتاح API وسترد جميع المفهرسات بالرمز 401. يُستخدم فقط على شبكة محلية موثوقة.",
      ko: "암호화되지 않은 HTTP로 Prowlarr에 접속할 때 필요합니다. 그렇지 않으면 API 키가 전송되지 않아 모든 인덱서가 401로 응답합니다. 신뢰할 수 있는 로컬 네트워크에서만 사용하세요.",
      "zh-Hant":
        "透過未加密的 HTTP 存取 Prowlarr 時必須啟用，否則不會傳送 API 金鑰，所有索引器都會回覆 401。僅限可信任的區域網路使用。",
      vi: "Cần bật khi truy cập Prowlarr qua HTTP không mã hóa; nếu không, khóa API sẽ không được gửi và mọi trình lập chỉ mục sẽ trả lời 401. Chỉ dùng trên mạng nội bộ đáng tin cậy.",
      id: "Wajib saat mengakses Prowlarr melalui HTTP tanpa enkripsi; jika tidak, kunci API tidak akan dikirim dan setiap pengindeks akan menjawab 401. Gunakan hanya di jaringan lokal tepercaya.",
    },
  "Required. Found in SABnzbd Config → General → API Key.": {
    es: "Obligatorio. Se encuentra en SABnzbd: Config → General → API Key.",
    "zh-Hans": "必填。位置：SABnzbd 的 Config → General → API Key。",
    hi: "आवश्यक। SABnzbd में यहाँ मिलेगा: Config → General → API Key.",
    de: "Erforderlich. Zu finden in SABnzbd unter Config → General → API Key.",
    ja: "必須です。SABnzbd の Config → General → API Key にあります。",
    fr: "Obligatoire. Dans SABnzbd, sous Config → General → API Key.",
    "pt-BR": "Obrigatório. No SABnzbd, em Config → General → API Key.",
    ar: "مطلوب. تجده في SABnzbd ضمن Config → General → API Key.",
    ko: "필수 항목입니다. SABnzbd의 Config → General → API Key에서 확인할 수 있습니다.",
    "zh-Hant": "必填。位置：SABnzbd 的 Config → General → API Key。",
    vi: "Bắt buộc. Tìm trong SABnzbd tại Config → General → API Key.",
    id: "Wajib diisi. Buka SABnzbd, lalu pilih Config → General → API Key.",
  },
