    ar: "عيّن رابط Webhook لمشاركة إحصاءات مكتبتك بنقرة واحدة في قناة Discord.",
    ko: "Webhook URL을 설정하면 라이브러리 통계를 Discord 채널에 한 번의 클릭으로 공유할 수 있습니다.",
    "zh-Hant": "設定 Webhook URL，即可一鍵將資料庫統計資料分享至 Discord 頻道。",
    vi: "Đặt URL webhook để chia sẻ thống kê thư viện của bạn lên kênh Discord chỉ bằng một lần nhấp.",
