  "Translate download client paths to paths accessible by Questarr. Required when Questarr and your download client run on separate machines or containers with different volume mounts.":
    {
      es: "Convierte las rutas que informa el cliente de descargas en rutas accesibles para Questarr. Es necesario cuando Questarr y el cliente se ejecutan en equipos distintos o en contenedores con montajes de volúmenes diferentes.",
      "zh-Hans":
        "将下载客户端报告的路径转换为 Questarr 可访问的路径。当 Questarr 与下载客户端运行在不同设备上，或位于卷挂载路径不同的容器中时，需要进行此配置。",
      hi: "डाउनलोड क्लाइंट द्वारा बताई गई फ़ाइल पथों को Questarr के लिए सुलभ पथों में बदलें। अलग-अलग मशीनों या अलग वॉल्यूम माउंट वाले कंटेनरों पर चलने पर यह आवश्यक है।",
      de: "Wandelt die vom Download-Client gemeldeten Pfade in Pfade um, auf die Questarr zugreifen kann. Erforderlich, wenn Questarr und der Download-Client auf verschiedenen Rechnern oder in Containern mit unterschiedlichen Volume-Einbindungen laufen.",
      ja: "ダウンロードクライアントが報告するパスを、Questarr からアクセスできるパスに変換します。Questarr とクライアントが別のマシン、または異なるボリュームをマウントしたコンテナで動作する場合に必要です。",
      fr: "Convertit les chemins indiqués par le client de téléchargement en chemins accessibles par Questarr. Nécessaire lorsque Questarr et le client fonctionnent sur des machines distinctes ou dans des conteneurs avec des montages de volumes différents.",
      "pt-BR":
        "Converta os caminhos informados pelo cliente de download em caminhos acessíveis ao Questarr. Isso é necessário quando o Questarr e o cliente estão em máquinas diferentes ou em contêineres com pontos de montagem de volumes diferentes.",
      ar: "حوّل المسارات التي يبلّغ عنها عميل التنزيل إلى مسارات يمكن لـ Questarr الوصول إليها. يلزم ذلك عندما يعمل Questarr وعميل التنزيل على جهازين مختلفين أو داخل حاويتين لهما مسارات تركيب وحدات تخزين مختلفة.",
      ko: "다운로드 클라이언트가 보고하는 경로를 Questarr에서 접근할 수 있는 경로로 변환합니다. Questarr와 클라이언트가 서로 다른 컴퓨터에서 실행되거나 볼륨 마운트 경로가 다른 컨테이너에서 실행될 때 필요합니다.",
      "zh-Hant":
        "將下載用戶端回報的路徑轉換為 Questarr 可存取的路徑。當 Questarr 與下載用戶端在不同電腦執行，或位於磁碟區掛載路徑不同的容器時，需要設定此項目。",
      vi: "Chuyển đường dẫn do ứng dụng tải xuống báo cáo thành đường dẫn Questarr có thể truy cập. Cần thiết khi Questarr và ứng dụng tải xuống chạy trên các máy khác nhau hoặc trong container có điểm gắn volume khác nhau.",
      id: "Ubah jalur yang dilaporkan klien unduhan menjadi jalur yang dapat diakses Questarr. Diperlukan jika Questarr dan klien berjalan di mesin berbeda atau container dengan mount volume yang berbeda.",
    },
